Ext._define('rh.replacement.WindowUpdateDocument', {
    extend: 'Ext.Window',

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.applyIf(
            cfg,
            {
                title: 'Atualizar Publicação da Tabela de Substituição Automática'
            }
        );

        Ext.apply(
            cfg,
            {
                width: 500,
                height: 110,
                resizable: false,
                border: false,
                frame: true,
                modal: true,
                items: [
                    this.getFormPanel()
                ]
            }
        );

        rh.replacement.WindowUpdateDocument.superclass.constructor.call(this, cfg);
    },

    getFormPanel: function(cfg) {
        if(!this._formPanel)
            this._formPanel = Ext._create('Ext.form.FormPanel', {
                border: false,
                height: 80,
                frame: true,
                items: [
                    {
                        xtype: "rest-autocompletefield",
                        fieldLabel: "Publicação",
                        allowBlank: false,
                        rest: "rh.publicacao.Restful",
                        name: "document"
                    },
                ],
                buttons: [{
                    text: 'Salvar',
                    scope: this,
                    handler: function() {
                        this._save(this.getFormPanel().getForm().getValues());
                    }
                }]
            });
        return this._formPanel;
    },

    _save: function(params){
        this.updateDocument(params);
    },

    updateDocument: function(params){
        var rest = Ext._create("rh.replacement.Restful", {});
        var mask = new Ext.LoadMask(this.getEl(), {msg: 'Atualizando informações.'});
        var wnd = this;

        mask.show();
        rest.updateDocument(
            params,
            {
                scope: this,
                fn: function(rst) {
                    Ext.Msg.show({
                        title: 'Informando',
                        icon: Ext.Msg.INFO,
                        buttons: Ext.Msg.OK,
                        msg: rst.message
                    });
                    wnd.close();
                }
            },
            {
                fn: function(message) {
                    Ext.Msg.show({
                        title: 'Informando',
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK,
                        msg: message
                    });
                }
            },
            {
                fn: function() {
                    mask.hide();
                }
            }
        );
    }
});

